{
  "world_id": "wld_dyson_swarm_embers",
  "name": "The Tithe of Embers",
  "description": "Eleven thousand years after the sun began to gutter, humanity survives in the Swarm: a loose cloud of habitat shells, mirror sails and relay stations orbiting a dimming red star. Light is rationed, and so is time, because the Swarm is so wide that a message between its far edges takes days to arrive. Couriers carry the sealed physical letters that bind the habitats into one civilization. This is a thoughtful science fiction world about inheritance, patience and the ethics of reading a letter meant for someone who is long dead. Its central discovery is that the builders of the Swarm left a message in the one place nobody thought to listen: the slow drift of the habitats themselves. The message asks a question that the dying star makes urgent. Should the Swarm keep holding on, or let go?",
  "locations": [
    {
      "id": "loc_ember_hub",
      "name": "Ember Hub",
      "description": "The largest habitat in the Swarm and its administrative heart. It is a slowly rotating cylinder built around a captive fusion ember. The Allocation Court sits here and decides who receives how many hours of starlight each cycle."
    },
    {
      "id": "loc_lantern_ring",
      "name": "The Lantern Ring",
      "description": "A chain of mirror sails and orchard habitats that focuses the star's weakening light onto farm decks. Its inhabitants measure age in harvests and treat every dimming of the sails as a death in the family."
    },
    {
      "id": "loc_courier_dock",
      "name": "Tallow Dock",
      "description": "A crowded relay station where couriers rest, repair their sail-skiffs and trade rumours. Its walls are covered with the names of couriers who never arrived at their destinations."
    },
    {
      "id": "loc_cradle_habitat",
      "name": "Cradle Habitat",
      "description": "The oldest surviving habitat, with corroded hull plates and rooms built to a human scale slightly larger than modern people. Its inhabitants are caretakers who maintain the builders' original instruments without understanding most of them."
    },
    {
      "id": "loc_null_shade",
      "name": "The Null Shade",
      "description": "A region of the Swarm where the habitats' shadows overlap so completely that no starlight reaches it. Cold-adapted outcasts live here, and the builders' message is clearest here, where nothing else is shining."
    },
    {
      "id": "loc_first_panel",
      "name": "First Panel",
      "description": "A single enormous collector panel at the inner edge of the Swarm, closest to the star. It is scorched, sacred to some, and the place where the builders' signal appears to originate."
    }
  ],
  "factions": [
    {
      "id": "fac_allocation_court",
      "name": "The Allocation Court",
      "description": "The governing body that rations starlight and enforces the Tithe, the share of each habitat's energy surrendered to the common reserve. It believes strict order is the only way the Swarm survives the star's decline.",
      "location_ids": ["loc_ember_hub", "loc_lantern_ring"]
    },
    {
      "id": "fac_couriers_guild",
      "name": "The Couriers' Guild",
      "description": "An independent guild that carries sealed letters between habitats and swears never to read them. Its members are the only people who see the whole Swarm, and they trade in trust.",
      "location_ids": ["loc_courier_dock", "loc_ember_hub"]
    },
    {
      "id": "fac_caretakers",
      "name": "The Cradle Caretakers",
      "description": "Keepers of the builders' oldest machines, who hold that the Swarm was designed to end gracefully. They interpret the builders' silence as consent to decline.",
      "location_ids": ["loc_cradle_habitat", "loc_first_panel"]
    },
    {
      "id": "fac_shade_kin",
      "name": "The Shade Kin",
      "description": "Descendants of those who were denied a light allocation and learned to live in the dark. They hear the builders' message as a voice and do not accept anyone else's translation of it.",
      "location_ids": ["loc_null_shade"]
    }
  ],
  "rules": [
    {
      "id": "rul_light_lag",
      "statement": "No signal crosses the Swarm faster than light, so a message between distant habitats takes days, and sometimes weeks, to arrive. Important decisions are therefore carried by couriers and not broadcast.",
      "category": "physics"
    },
    {
      "id": "rul_resonance_drift",
      "statement": "The orbits of the habitats shift in slow, patterned resonances, and the builders encoded information in the timing of these shifts. A message can be read only by comparing records kept across many decades.",
      "category": "physics"
    },
    {
      "id": "rul_sealed_letters",
      "statement": "A courier may never open a sealed letter. A letter opened by its carrier is considered void, and the carrier is struck from the Guild's roll.",
      "category": "social"
    },
    {
      "id": "rul_tithe",
      "statement": "Every habitat must surrender one tenth of its collected starlight to the common reserve. Refusal of the Tithe is the gravest crime in the Swarm.",
      "category": "social"
    },
    {
      "id": "rul_closed_loops",
      "statement": "Every habitat recycles air, water and waste in a closed loop. The loss of a single habitat's loop means the permanent loss of its population, because no habitat has the capacity to take in more than a few hundred refugees.",
      "category": "technology"
    },
    {
      "id": "rul_sail_navigation",
      "statement": "Couriers travel only by light sails and gravity assists. Journeys time themselves to the star's dimming cycle, and no vessel carries enough fuel to alter course in a hurry.",
      "category": "technology"
    },
    {
      "id": "rul_builders_unknown",
      "statement": "No living person has seen a builder. Everything known about them is inferred from their machines, and each faction reads the same evidence differently.",
      "category": "other"
    }
  ],
  "history": [
    {
      "id": "evt_raising_of_swarm",
      "name": "The Raising of the Swarm",
      "description": "The builders assembled the first habitats and collector panels around the then-bright star. They left behind the Cradle Habitat and an unexplained clause: every habitat was built to drift on a schedule that outlasts any living memory.",
      "era": "Deep Antiquity",
      "location_ids": ["loc_cradle_habitat", "loc_first_panel"]
    },
    {
      "id": "evt_builders_silence",
      "name": "The Builders' Silence",
      "description": "The builders vanished, leaving no record of where they went. Early settlers took the silence as abandonment, and later generations argued over whether it was a lie.",
      "era": "Age of Settling",
      "location_ids": ["loc_cradle_habitat"]
    },
    {
      "id": "evt_first_dimming",
      "name": "The First Dimming",
      "description": "The star's output dropped measurably for the first time. The Allocation Court was founded in the panic that followed and imposed the Tithe.",
      "era": "Age of Rationing",
      "location_ids": ["loc_ember_hub", "loc_lantern_ring"]
    },
    {
      "id": "evt_the_shading",
      "name": "The Shading of the Null",
      "description": "The Court re-routed several mirror sails, and an entire region of the Swarm fell into permanent shadow. The inhabitants were declared dormant and cut from the allocation roll, and the Shade Kin were born from their survivors.",
      "era": "Age of Rationing",
      "location_ids": ["loc_null_shade"]
    },
    {
      "id": "evt_guild_oath",
      "name": "The Guild Oath",
      "description": "After a courier leaked a letter and triggered a war between two habitats, the Couriers' Guild adopted its oath never to read what it carries.",
      "era": "Age of Rationing",
      "location_ids": ["loc_courier_dock"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_light_and_shade",
      "name": "The Debt of the Null",
      "description": "The Shade Kin claim the Court abandoned them and owe them restitution. The Court insists the Tithe cannot be spared. The builders' message, if it is real, could be used to prove either side right.",
      "faction_ids": ["fac_allocation_court", "fac_shade_kin"]
    },
    {
      "id": "cnf_who_reads",
      "name": "Who May Read the Message",
      "description": "The Caretakers want the message kept secret, since it may call for the Swarm to end. The Guild's oath forbids its couriers from reading it, yet only a courier has carried it. The Court wants it as a tool of governance.",
      "faction_ids": ["fac_caretakers", "fac_couriers_guild", "fac_allocation_court"]
    }
  ]
}

