{
  "world_id": "wld_the_unmoored_meridian",
  "name": "The Unmoored Meridian",
  "description": "The luxury liner Meridian Regina left port decades ago and vanished. It now drifts through a permanent, bone-cold fog that swallows horizons, radio signals and any sense of time. A salvage crew boards expecting an empty hulk to strip for profit. Instead they find a ship that is still hosting its voyage. Tables are laid, orchestras tune in sealed ballrooms, and the former passengers keep playing their roles. The Meridian does not haunt its visitors so much as enroll them. Every salvaged object, name and memory is added to a manifest that can only be balanced by keeping someone aboard. The mood is oppressive: low ceilings of grey vapor, damp brass, whispered etiquette, and the slow realization that the crew's own arrival was already recorded in the ship's log.",
  "locations": [
    {
      "id": "loc_grand_saloon",
      "name": "The Grand Saloon",
      "description": "A vast, candlelit ballroom where fog pools knee-deep across the parquet floor. The long-dead passengers dine and dance in fixed loops, and each place setting is labeled with a name. New names appear in fresh ink as the salvage crew explores."
    },
    {
      "id": "loc_ledger_hold",
      "name": "The Ledger Hold",
      "description": "A flooded cargo deck below the waterline, lined with filing cabinets and rusted shelving. Its walls are damp with condensing fog. The Purser's manifests are kept here, and the ship's true accounting of who belongs aboard is recorded in them."
    }
  ],
  "factions": [
    {
      "id": "fac_salvage_crew",
      "name": "The Halloran Salvage Crew",
      "description": "A debt-ridden crew of six who boarded under a salvage contract. They are divided between those who want to strip the ship quickly and those who have started to feel the manifest pulling at them.",
      "location_ids": ["loc_grand_saloon", "loc_ledger_hold"]
    },
    {
      "id": "fac_dining_court",
      "name": "The Dining Court",
      "description": "The undead first-class passengers, bound to an endless service of dinner. They are polite, patient and relentless. They treat every newcomer as an honored guest whose seat must be filled forever.",
      "location_ids": ["loc_grand_saloon"]
    },
    {
