{
  "world_id": "wld_plainlaw_realm",
  "name": "The Plainlaw Realm",
  "description": "The kingdom of Harrowmere prospers on one law: no arcane power may be practiced, taught, owned or spoken of. Its grain is counted, its roads are straight and its people are proud to be ordinary. The kingdom's safety depends on the old wards, a ring of iron-and-salt boundary works that the Crown calls plain engineering. They are failing. Cracks run through the stones, the dead walk the marsh edge at dusk, and the Crown answers with more executions of anyone suspected of arcane taint. The truth is buried in the Crown's ledgers. The wards are fed by the very arcane power the realm outlaws, drawn from the condemned. The tone is grim: cold rain, rationed hope and a government that would rather burn the truth than admit it.",
  "locations": [
    {
      "id": "loc_harrowmere_citadel",
      "name": "Harrowmere Citadel",
      "description": "A squat, windowless seat of government where the Tally Court sits. Its lowest vaults hold the Ledger of Quiet, a record of every person put to the Silence."
    },
    {
      "id": "loc_saltgate_wall",
      "name": "The Saltgate Wall",
      "description": "A hundred-mile ring of iron-studded stone that holds the primary wards. Its lamps once burned steady white and now gutter green. Wallkeepers patrol it in shifts that few survive for long."
    },
    {
      "id": "loc_drownmoor",
      "name": "Drownmoor",
      "description": "A fog-choked marsh beyond the southern ward line. Hedge-folk hide here, and the restless dead have begun to gather at the places where the wall has weakened."
    },
    {
      "id": "loc_pennyfold",
      "name": "Pennyfold",
      "description": "A market town of tallymen, millers and informers. Neighbors sell each other to the Crown for coin and grain, and every household keeps an iron nail above the door as proof of loyalty."
    }
  ],
  "factions": [
    {
      "id": "fac_tally_court",
      "name": "The Tally Court",
      "description": "The judges and clerks who enforce the ban on arcane power. They privately know the wards depend on the condemned and keep this hidden even from the crown.",
      "location_ids": ["loc_harrowmere_citadel", "loc_pennyfold"]
    },
    {
      "id": "fac_wallkeepers",
      "name": "The Wallkeepers",
      "description": "Conscripted soldiers who tend the wards by hand. They have noticed that the lamps burn brightest after an execution day, and they are starting to ask why.",
      "location_ids": ["loc_saltgate_wall"]
    },
    {
      "id": "fac_hedge_remnant",
      "name": "The Hedge Remnant",
      "description": "Hunted practitioners of old arcane arts, hiding in the marsh. Some of them want to repair the wards without sacrifice. Others want to see the wall fall.",
      "location_ids": ["loc_drownmoor"]
    }
  ],
  "rules": [
    {
      "id": "rul_ward_upkeep",
      "statement": "Every ward on the Saltgate Wall must be refreshed by the Tally Court's Silence rite, which is performed only on a condemned person.",
      "category": "metaphysics"
    },
    {
      "id": "rul_iron_nails",
      "statement": "Cold iron weakens the restless dead, but a nail left in place for more than a generation rusts and loses its power.",
      "category": "physics"
    },
    {
      "id": "rul_name_ban",
      "statement": "Speaking of arcane power in public is a crime in itself, punishable by the Silence.",
      "category": "social"
    },
    {
      "id": "rul_ledger_binding",
      "statement": "A name written in the Ledger of Quiet cannot be removed. The ledger itself is the anchor for the ward network.",
      "category": "metaphysics"
    },
    {
      "id": "rul_plain_craft",
      "statement": "Only guild-licensed engineering is lawful. Anything that cannot be explained in a guild manual is treated as arcane.",
      "category": "technology"
    }
  ],
  "history": [
    {
      "id": "evt_founding_of_wall",
      "name": "Raising of the Saltgate Wall",
      "description": "After the Weeping War, the first Tally Judges raised the wall and its wards, telling the people it was only fortification.",
      "era": "Age of Mortar",
      "location_ids": ["loc_saltgate_wall"]
    },
    {
      "id": "evt_great_silence",
      "name": "The Great Silence",
      "description": "The Crown outlawed all arcane practice and put thousands to the Silence in one winter. The wards burned brightest that season, and the Court has kept the reason secret since.",
      "era": "Age of Mortar",
      "location_ids": ["loc_harrowmere_citadel", "loc_pennyfold"]
    },
    {
      "id": "evt_first_green_lamp",
      "name": "The First Green Lamp",
      "description": "A single lamp on the wall turned green and failed to recover. The Wallkeepers' report was struck from the record.",
      "era": "Age of Ash",
      "location_ids": ["loc_saltgate_wall", "loc_drownmoor"]
    }
  ],
  "conflicts": [
    {
      "id": "cnf_truth_of_the_wall",
      "name": "The Cost of the Wall",
      "description": "The Wallkeepers are close to proving that the wards depend on executions. The Tally Court will kill to keep that quiet, and the Hedge Remnant could repair the wards but only by openly breaking the law.",
      "faction_ids": ["fac_tally_court", "fac_wallkeepers", "fac_hedge_remnant"]
    },
    {
      "id": "cnf_marsh_purge",
      "name": "The Marsh Purge",
      "description": "The Tally Court wants to burn Drownmoor and feed the wards with the Hedge Remnant. The Remnant's own factions disagree on whether to flee or fight.",
      "faction_ids": ["fac_tally_court", "fac_hedge_remnant"]
    }
  ]
}

